  "vocab-8": {"promptNative": "«Equipa» significa...", "options": ["squadra (sportiva)", "attrezzatura", "sala del personale", "divisa"], "explain": "La parola portoghese per una squadra sportiva/di lavoro. Il portoghese brasiliano usa invece 'time' (presa dall’inglese \"team\").", "wrongNote": "“Equipa” significa “team”. La parola portoghese per una squadra sportiva/di lavoro. Il portoghese brasiliano usa invece 'time' (presa dall’inglese \"team\").", "distractorNotes": {"attrezzatura": "“equipment” è un distrattore — “Equipa” non significa questo; significa “team”.", "sala del personale": "“staff room” è un distrattore — “Equipa” non significa questo; significa “team”.", "divisa": "“uniform” è un distrattore — “Equipa” non significa questo; significa “team”."}},
  "vocab-9": {"promptNative": "«Fixe» (informale) significa...", "options": ["forte/figo", "aggiustato/riparato", "formale", "caro"], "explain": "La parola informale di tutti i giorni del portoghese per \"genial\" o \"increíble.\" Il portoghese brasiliano usa invece 'legal' per lo stesso significato colloquiale.", "wrongNote": "“Fixe” significa “cool/great”. La parola informale di tutti i giorni del portoghese per \"genial\" o \"increíble.\" Il portoghese brasiliano usa invece 'legal' per lo stesso significato colloquiale.", "distractorNotes": {"aggiustato/riparato": "“fixed/repaired” è un distrattore — “Fixe” non significa questo; significa “cool/great”.", "formale": "“formal” è un distrattore — “Fixe” non significa questo; significa “cool/great”.", "caro": "“expensive” è un distrattore — “Fixe” non significa questo; significa “cool/great”."}},
