  "trad-27": {"prompt": "Traduci: '¡Bienvenido!' (a un uomo)", "promptNative": "Saluto di benvenuto (uomo).", "explain": "'Bem-vindo' (letteralmente 'bien venido') è il saluto; concorda con la persona, quindi a un uomo tocca 'bem-vindo'.", "wrongNote": "La traduzione naturale è “Bem-vindo!”. 'Bem-vindo' (letteralmente 'bien venido') è il saluto; concorda con la persona, quindi a un uomo tocca 'bem-vindo'.", "distractorNotes": {"Venha bem!": "“Venha bem!” è una traduzione non idiomatica — un portoghese non lo direbbe così; la versione naturale è “Bem-vindo!”.", "Boa vinda!": "“Boa vinda!” è una traduzione non idiomatica — un portoghese non lo direbbe così; la versione naturale è “Bem-vindo!”.", "Bem chegado!": "“Bem chegado!” è una traduzione non idiomatica — un portoghese non lo direbbe così; la versione naturale è “Bem-vindo!”."}},
  "trad-28": {"prompt": "Traduci: '¿Cuánto cuesta?'", "promptNative": "Chiedere il prezzo.", "explain": "Il prezzo si chiede con 'quanto custa?' — '¿cuánto cuesta?'; un letterale 'how much is it' non funziona.", "wrongNote": "La traduzione naturale è “Quanto custa?”. Il prezzo si chiede con 'quanto custa?' — '¿cuánto cuesta?'; un letterale 'how much is it' non funziona.", "distractorNotes": {"Como muito é?": "“Como muito é?” è una traduzione non idiomatica — un portoghese non lo direbbe così; la versione naturale è “Quanto custa?”.", "Que custa?": "“Que custa?” è una traduzione non idiomatica — un portoghese non lo direbbe così; la versione naturale è “Quanto custa?”.", "Quanto dinheiro?": "“Quanto dinheiro?” è una traduzione non idiomatica — un portoghese non lo direbbe così; la versione naturale è “Quanto custa?”."}},
  "trad-29": {"prompt": "Traduci: '¿Qué hora es?'", "promptNative": "Chiedere l’ora.", "explain": "Il portoghese chiede l’ora al plurale — 'que horas são?' ('¿qué horas son?') — e 'tempo' qui significherebbe il tempo atmosferico.", "wrongNote": "La traduzione naturale è “Que horas são?”. Il portoghese chiede l’ora al plurale — 'que horas são?' ('¿qué horas son?') — e 'tempo' qui vorrebbe dire il tempo atmosferico.", "distractorNotes": {"Quantas horas?": "“Quantas horas?” è una traduzione non idiomatica — un portoghese non lo direbbe così; la versione naturale è “Que horas são?”.", "Que tempo é?": "“Que tempo é?” è una traduzione non idiomatica — un portoghese non lo direbbe così; la versione naturale è “Que horas são?”.", "Qual hora é?": "“Qual hora é?” è una traduzione non idiomatica — un portoghese non lo direbbe così; la versione naturale è “Que horas são?”."}},
  "trad-30": {"prompt": "Traduci: 'No entiendo.'", "promptNative": "Dire che non hai capito.", "explain": "In Portogallo 'perceber' è il verbo di tutti i giorni per 'entender', quindi 'não percebo' — i brasiliani dicono 'não entendo'.", "wrongNote": "La traduzione naturale è “Não percebo.”. In Portogallo 'perceber' è il verbo di tutti i giorni per 'entender', quindi 'não percebo' — i brasiliani dicono 'não entendo'.", "distractorNotes": {"Não entendo.": "“Não entendo.” è una traduzione non idiomatica — un portoghese non lo direbbe così; la versione naturale è “Não percebo.”.", "Não ouço.": "“Não ouço.” è una traduzione non idiomatica — un portoghese non lo direbbe così; la versione naturale è “Não percebo.”.", "Não compreendo isso.": "“Não compreendo isso.” è una traduzione non idiomatica — un portoghese non lo direbbe così; la versione naturale è “Não percebo.”."}},
  "trad-31": {"prompt": "Traduci: 'Con permiso.' (per passare)", "promptNative": "Per chiedere di passare.", "explain": "'Com licença' (letteralmente 'con permiso') è quello che si dice per passare accanto a qualcuno o alzarsi da tavola.", "wrongNote": "La traduzione naturale è “Com licença.”. 'Com licença' (letteralmente 'con permiso') è quello che si dice per passare accanto a qualcuno o alzarsi da tavola.", "distractorNotes": {"Licença dá?": "“Licença dá?” è una traduzione non idiomatica — un portoghese non lo direbbe così; la versione naturale è “Com licença.”.", "Perdoe-me.": "“Perdoe-me.” è una traduzione non idiomatica — un portoghese non lo direbbe così; la versione naturale è “Com licença.”.", "Com permissão.": "“Com permissão.” è una traduzione non idiomatica — un portoghese non lo direbbe così; la versione naturale è “Com licença.”."}},
